using Godot;
using System.Collections.Generic;

/// <summary>
/// Playback gain for mission music, so every mission's track sits at the same level, about 9 LU
/// under mission speech. Mission music used to play at +24 dB on Master, which put the default
/// track about 33 LU over speech and drove it far past full scale. The table
/// <c>res://assets/audio/music_gain.json</c> is generated by <c>tools/assets/music_gain.py</c> from
/// every <c>MusicPath</c> in <c>scripts/gameplay</c>; <c>CodeLevel</c> plays the track on
/// <see cref="Bus"/> at <see cref="GainDb"/>. A missing table or entry gives 0 dB.
/// </summary>
public static class MusicGain
{
    /// <summary>Path of the generated gain table.</summary>
    public const string TablePath = "res://assets/audio/music_gain.json";
    /// <summary>Bus mission music plays on (sends to Master, so the menu volume slider controls it).</summary>
    public const string Bus = "Music";
    /// <summary>Upper bound on any music gain; same value as MAX_GAIN_DB in music_gain.py.</summary>
    public const float MaxGainDb = 30f;

    private static readonly GainTable Table = new(TablePath, MaxGainDb);

    /// <summary>Parses music table JSON (see <see cref="GainTable.Parse"/>) with the music gain limit.</summary>
    public static Dictionary<string, float> Parse(string json) => GainTable.Parse(json, MaxGainDb);

    /// <summary>
    /// Gain in dB for a music resource path, or 0 when the table or the entry is absent. A missing
    /// entry logs a warning, because it means a mission track was added or renamed without
    /// re-running tools/assets/music_gain.py and would play at its raw level.
    /// </summary>
    public static float GainDb(string resPath)
    {
        if (!Table.Contains(resPath))
            GD.PushWarning($"MusicGain: no gain for {resPath}; run tools/assets/music_gain.py");
        return Table.GainDb(resPath);
    }
}
